import{A as e,f as t,h as n,t as r}from"./chunks/plugin-vue_export-helper.I53torQa.js";var i=JSON.parse(`{"title":"昇腾软硬件架构与资料导读","description":"梳理昇腾 NPU 从计算单元、存储层次、设备互联到 CANN、框架适配和通信库的软件栈，提供官方文档与论文阅读入口，并明确芯片代际、设备口径和能力边界。","frontmatter":{"title":"昇腾软硬件架构与资料导读","description":"梳理昇腾 NPU 从计算单元、存储层次、设备互联到 CANN、框架适配和通信库的软件栈，提供官方文档与论文阅读入口，并明确芯片代际、设备口径和能力边界。"},"headers":[],"relativePath":"ascend/architecture/index.md","filePath":"ascend/architecture/index.md","lastUpdated":1793959026000}`),a={name:`ascend/architecture/index.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="昇腾软硬件架构与资料导读" tabindex="-1">昇腾软硬件架构与资料导读 <a class="header-anchor" href="#昇腾软硬件架构与资料导读" aria-label="Permalink to “昇腾软硬件架构与资料导读”">​</a></h1><p>本目录用于整理昇腾（Ascend）软硬件架构的介绍与学习资料，重点解释硬件如何执行计算、软件如何组织任务，以及两者如何影响训练和推理性能。具体应用方案与实验记录可结合 <a href="https://jianzhnie.github.io/llmtechsite/ascend/" target="_blank" rel="noreferrer">Ascend 生态文档</a> 阅读。</p><h2 id="_1-内容范围" tabindex="-1">1. 内容范围 <a class="header-anchor" href="#_1-内容范围" aria-label="Permalink to “1. 内容范围”">​</a></h2><ul><li><strong>NPU 硬件架构</strong>：AI Core、矩阵与向量计算单元、存储层次、数据搬运和同步机制，以及 Ascend 910C 等具体型号的公开资料。</li><li><strong>设备与集群互联</strong>：物理卡、计算 die、逻辑 device 与训练 rank 的映射，服务器和超节点拓扑，以及链路对通信的影响。</li><li><strong>基础软件栈</strong>：驱动、固件、CANN（Compute Architecture for Neural Networks），以及运行时、编译和算子执行之间的关系。</li><li><strong>算子开发与通信</strong>：Ascend C 的编程模型、流水线与内存管理，HCCL 集合通信及设备侧通信的适用条件。</li><li><strong>框架接入</strong>：PyTorch / torch_npu、MindSpore 等框架如何使用底层能力，关注模块职责与版本兼容关系。</li></ul><p>后续专题文章按上述范围放入本目录，使用描述性英文文件名，例如 <code>ascend-910c-architecture.md</code>、<code>cann-software-stack.md</code>；这些名称是组织示例，并非已有文章。配图按 <code>images/&lt;article-slug&gt;/</code> 分组。</p><h2 id="_2-建议阅读路线" tabindex="-1">2. 建议阅读路线 <a class="header-anchor" href="#_2-建议阅读路线" aria-label="Permalink to “2. 建议阅读路线”">​</a></h2><p>本目录文章：<a href="https://jianzhnie.github.io/llmtechsite/ascend/architecture/ascend-910b3-cann-architecture" target="_blank" rel="noreferrer">昇腾 910B3 硬件架构与 CANN 软件栈</a>。先结合该文建立软硬件整体视图，再按下述路线深入。</p><p>先建立 AI Core、存储与数据搬运的基础概念，再阅读 Ascend C 的任务执行与同步机制。理解单设备执行后，继续学习设备映射、互联拓扑与通信库，最后结合框架和具体模型分析性能。</p><p>阅读 910C 资料时，应分别回答三个问题：一颗计算 die 内部如何执行任务，一张物理卡如何暴露设备，以及多个设备如何组成训练通信域。物理卡数、device 数与 rank 数不能直接互换。</p><h2 id="_3-官方文档与论文入口" tabindex="-1">3. 官方文档与论文入口 <a class="header-anchor" href="#_3-官方文档与论文入口" aria-label="Permalink to “3. 官方文档与论文入口”">​</a></h2><h3 id="_3-1-官方资料" tabindex="-1">3.1 官方资料 <a class="header-anchor" href="#_3-1-官方资料" aria-label="Permalink to “3.1 官方资料”">​</a></h3><ul><li><a href="https://www.hiascend.com/document" target="_blank" rel="noreferrer">昇腾文档中心</a>：按实际 CANN 版本和目标产品查阅 AI Core 架构、Ascend C、运行时及 HCCL 文档。重点搜索“计算单元”“存储架构”“数据搬运”“流水线同步”等主题。</li><li><a href="https://www.huawei.com/en/news/2025/9/hc-xu-keynote-speech" target="_blank" rel="noreferrer">华为：Building a Better, Intelligent World through an Open AI Ecosystem</a>：2025 年 9 月的官方介绍，说明 Ascend 910C、Atlas 900 A3 SuperPoD 与 CloudMatrix384 的产品关系；不作为微架构和逐链路带宽规格手册。</li></ul><h3 id="_3-2-系统论文与站内解读" tabindex="-1">3.2 系统论文与站内解读 <a class="header-anchor" href="#_3-2-系统论文与站内解读" aria-label="Permalink to “3.2 系统论文与站内解读”">​</a></h3><ul><li><a href="https://arxiv.org/html/2605.23764v2" target="_blank" rel="noreferrer">HyperParallel-MoE 论文</a>：结合 AIC/AIV 异构执行、事件同步和通信计算重叠理解架构如何影响 MoE 调度。配套阅读：<a href="https://jianzhnie.github.io/llmtechsite/ascend/ecosystem/hyperparallel-moe" target="_blank" rel="noreferrer">多核交错调度解读</a>。</li><li><a href="https://arxiv.org/html/2609.21594v1" target="_blank" rel="noreferrer">HyperParallel-FSDP 论文</a>：关注拓扑感知训练与具体实验中的物理卡、die 和 rank 口径，不将单一部署配置视为所有系统的默认映射。</li><li><a href="https://jianzhnie.github.io/llmtechsite/ascend/ecosystem/moonep-ascend-910c" target="_blank" rel="noreferrer">MoonEP 适配 Ascend 910C</a>：从工程实践理解主机规划、MTE 数据搬运、对称堆和通信同步；适配实现的限制不等同于芯片全部能力的边界。</li></ul><h2 id="_4-阅读与引用约定" tabindex="-1">4. 阅读与引用约定 <a class="header-anchor" href="#_4-阅读与引用约定" aria-label="Permalink to “4. 阅读与引用约定”">​</a></h2><p>具体参数应注明芯片型号、资料版本和计量范围，区分单 die 与整卡、单向与双向带宽、理论峰值与实测有效值。系列通用架构和后续型号的新增特性不能直接套用到 910C。</p><p>HCCL 是集合通信软件库，HCCS 是硬件互联相关技术名称，两者不应混用。支持某种集合通信，也不自动意味着任意拓扑都支持相同的设备侧远端访问或同步语义。</p><p>整理资料时优先引用官方文档与原始论文，明确区分产品规格、论文配置、工程推导和本地实验。未公开或未核实的核数、容量和带宽，不用二手参数拼成确定的架构结论。</p>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};